from __future__ import annotations; import json; from pathlib import Path; from common.testing.reverify_real_corpus import ReverifyResult, compare_scores, render_report, reverify_case; _TRUTH = {'opening_balance': '100.00', 'closing_balance': '130.00', 'transactions': [{'date': '2026-01-02', 'description': 'Coffee shop', 'amount': '-5.00'}, {'date': '2026-01-05', 'description': 'Salary credit', 'amount': '50.00'}]}; _perfect = lambda: json.loads(json.dumps(_TRUTH))
def test_compare_scores_no_change_when_fresh_matches_committed() -> None: result = compare_scores('case-1', old_extracted=_perfect(), new_extracted=_perfect(), truth=_TRUTH); assert result.verdict == 'no_change'; assert result.old_score == result.new_score == 1.0; _m1_old = _perfect(); _m1_new = _perfect(); _m1_new['transactions'][0]['amount'] = '-500.00'; _m1_result = compare_scores('case-1', old_extracted=_m1_old, new_extracted=_m1_new, truth=_TRUTH); assert _m1_result.verdict == 'regressed'; assert _m1_result.new_score < _m1_result.old_score; _m2_old = _perfect(); _m2_old['transactions'][0]['amount'] = '-500.00'; _m2_new = _perfect(); _m2_result = compare_scores('case-1', old_extracted=_m2_old, new_extracted=_m2_new, truth=_TRUTH); assert _m2_result.verdict == 'improved'; assert _m2_result.new_score > _m2_result.old_score; _m3_result = compare_scores('case-1', old_extracted=_perfect(), new_extracted=None, truth=_TRUTH); assert _m3_result.verdict == 'recording_failed'; assert _m3_result.new_score is None; _m4_old = _perfect(); _m4_new = _perfect(); _m4_result = compare_scores('case-1', old_extracted=_m4_old, new_extracted=_m4_new, truth=_TRUTH, epsilon=1e-06); assert _m4_result.verdict == 'no_change'; _m5_results = [ReverifyResult('a', 1.0, 1.0, 'no_change', 'matches'), ReverifyResult('b', 1.0, 0.5, 'regressed', 'regressed detail text')]; _m5_report = render_report(_m5_results); assert all((_m5_result.case_id in _m5_report for _m5_result in _m5_results)); _m5_detail_text = _m5_results[1].detail; assert _m5_detail_text in _m5_report
def _write_case_files(tmp_path: Path, case_id: str, *, extracted: dict, truth: dict) -> None: cassette_dir = tmp_path / 'cassettes'; ground_truth_dir = cassette_dir / 'ground_truth'; ground_truth_dir.mkdir(parents=True); (cassette_dir / f'{case_id}.json').write_text(json.dumps({'fingerprint': case_id, 'role': 'vision', 'tag': 'flow-only', 'request': {}, 'response': {'stream_text': json.dumps(extracted)}}), encoding='utf-8'); (ground_truth_dir / f'{case_id}.truth.json').write_text(json.dumps({'synthetic': True, 'modality': 'vision', 'institution_class': 'bank', 'edge_condition': 'happy_path', 'source': 'test', 'balance_reconciles': True, 'expected': truth}), encoding='utf-8')
def test_reverify_case_reads_committed_cassette_and_calls_live_extractor(tmp_path: Path) -> None:
    _write_case_files(tmp_path, 'case-1', extracted=_perfect(), truth=_TRUTH); calls: list[Path] = []
    def fake_live(pdf_path: Path) -> dict: calls.append(pdf_path); return _perfect()
    pdf_path = tmp_path / 'statement.pdf'; pdf_path.write_bytes(b'%PDF-fake'); result = reverify_case('case-1', pdf_path, fake_live, cassette_dir=tmp_path / 'cassettes', ground_truth_dir=tmp_path / 'cassettes' / 'ground_truth'); assert calls == [pdf_path]; assert result.verdict == 'no_change'
def test_reverify_case_never_mutates_the_committed_cassette(tmp_path: Path) -> None:
    'AC-llm.14.4'; _write_case_files(tmp_path, 'case-1', extracted=_perfect(), truth=_TRUTH); cassette_path = tmp_path / 'cassettes' / 'case-1.json'; before = cassette_path.read_text(encoding='utf-8')
    def fake_live(pdf_path: Path) -> dict: regressed = _perfect(); regressed['closing_balance'] = '0.00'; return regressed
    pdf_path = tmp_path / 'statement.pdf'; pdf_path.write_bytes(b'%PDF-fake'); result = reverify_case('case-1', pdf_path, fake_live, cassette_dir=tmp_path / 'cassettes', ground_truth_dir=tmp_path / 'cassettes' / 'ground_truth'); assert result.verdict == 'regressed'; assert cassette_path.read_text(encoding='utf-8') == before
def test_reverify_case_missing_cassette_raises_not_a_silent_pass(tmp_path: Path) -> None:
    import pytest
    with pytest.raises(FileNotFoundError): reverify_case('nope', tmp_path / 'statement.pdf', lambda _pdf: _perfect(), cassette_dir=tmp_path / 'cassettes', ground_truth_dir=tmp_path / 'cassettes' / 'ground_truth')
